curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{"query": "query { __type(name: \"Query\") { fields { name args { name type { name kind ofType { name kind ofType { name kind } } } } } } }"}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
fields = data['data']['__type']['fields']
for f in fields:
    if f['name'] == 'documents':
        for a in f['args']:
            if a['name'] == 'filter':
                print(json.dumps(a, indent=2))
"
